from __future__ import annotations

import asyncio
from collections.abc import AsyncIterator
from typing import Generic, TypeVar

T = TypeVar("T")


class MultiCursorBuffer(Generic[T]):
    """An append-only async buffer that can be iterated by many consumers.

    Each iterator receives the full sequence of items from index zero, then
    suspends waiting for new items. Pushing an item wakes every suspended
    iterator; closing the buffer releases them so they terminate cleanly.
    """

    def __init__(self) -> None:
        self._items: list[T] = []
        self._closed = False
        # Futures for iterators currently waiting for new items. Its length is
        # the number of suspended iterators.
        self._wakeups: list[asyncio.Future[None]] = []

    def __len__(self) -> int:
        return len(self._items)

    def push(self, item: T) -> None:
        """Append an item and wake any iterators waiting for new items."""
        if self._closed:
            raise RuntimeError("cannot push to a closed MultiCursorBuffer")
        self._items.append(item)
        self._wake_all()

    def close(self) -> None:
        """Signal that no further items will be pushed and release waiters."""
        if self._closed:
            return
        self._closed = True
        self._wake_all()

    def _wake_all(self) -> None:
        wakeups, self._wakeups = self._wakeups, []
        for fut in wakeups:
            if not fut.done():
                fut.set_result(None)

    async def __aiter__(self) -> AsyncIterator[T]:
        cursor = 0
        while True:
            # Replay everything buffered so far from the current cursor.
            while cursor < len(self._items):
                yield self._items[cursor]
                cursor += 1

            if self._closed:
                return

            # Wait for a push or close to advance the buffer.
            fut: asyncio.Future[None] = asyncio.get_event_loop().create_future()
            self._wakeups.append(fut)
            try:
                await fut
            finally:
                if fut in self._wakeups:
                    self._wakeups.remove(fut)
