    """Return True if `namespace` starts with all segments in `prefix`.

    Each namespace segment is normalized (colon-suffix stripped) before
    comparison. A prefix segment that itself contains a colon is treated as an
    exact literal and compared against the raw namespace segment. An empty
    prefix matches any namespace; a prefix longer than the namespace never
    matches.
    """
    if not prefix:
        return True
    if len(prefix) > len(namespace):
        return False
    for ns_seg, p_seg in zip(namespace, prefix):
        if ":" in p_seg:
            if p_seg != ns_seg:
                return False
        elif p_seg != normalize_segment(ns_seg):
            return False
    return True


