    """Infer the channel name for an event from its `method` field.

    Returns None for unknown methods. For the `custom` method the channel is
    `custom:{name}` when the event data carries a non-empty `name`, otherwise
    just `custom`.
    """
    method = event.get("method")
    if method == "custom":
        data = event.get("data") or {}
        name = data.get("name") if isinstance(data, dict) else None
        if not name:
            name = event.get("name")
        if name:
            return f"custom:{name}"
        return "custom"
    if method is None:
        return None
    return _METHOD_CHANNELS.get(method)


