    if channel is None:
        return False

    channels = subscription.get("channels") or []
    if not _channel_listed(channel, channels):
        return False

    if "namespaces" in subscription:
        prefixes = subscription.get("namespaces")
        depth = subscription.get("depth")
        if not namespace_matches(_event_namespace(event), prefixes, depth):
            return False

    return True
